/**
 * Inline the tree-sitter WASM runtime and grammars into a TypeScript module.
 *
 * The shared bundler (`mcp-servers/scripts/bundle.mjs`) has no loader for
 * `.wasm`, and the built `dist/index.js` must run with no `node_modules`
 * beside it. So the binaries are gzipped and base64-encoded into
 * `src/generated/wasm-assets.ts`, which esbuild then inlines like any other
 * source. At runtime `zlib.gunzipSync` (a Node built-in) restores them.
 *
 * The output is gitignored and regenerated by `build`, `test` and
 * `typecheck`; it is skipped when the inputs have not changed.
 */

import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import * as path from 'node:path';
import { fileURLToPath } from 'node:url';
import { gzipSync } from 'node:zlib';

const here = path.dirname(fileURLToPath(import.meta.url));
const serverDir = path.resolve(here, '..');
const outFile = path.join(serverDir, 'src', 'generated', 'wasm-assets.ts');

/** Grammar id → file name inside @vscode/tree-sitter-wasm/wasm. */
const GRAMMARS = {
  javascript: 'tree-sitter-javascript.wasm',
  typescript: 'tree-sitter-typescript.wasm',
  tsx: 'tree-sitter-tsx.wasm',
  python: 'tree-sitter-python.wasm',
  go: 'tree-sitter-go.wasm',
  java: 'tree-sitter-java.wasm',
  rust: 'tree-sitter-rust.wasm',
  csharp: 'tree-sitter-c-sharp.wasm',
};

function findPackageDir(name) {
  let dir = serverDir;
  for (;;) {
    const candidate = path.join(dir, 'node_modules', ...name.split('/'));
    if (existsSync(path.join(candidate, 'package.json'))) return candidate;
    const parent = path.dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  throw new Error(`[gen-wasm-assets] cannot find package "${name}" — run npm install in mcp-servers/`);
}

const runtimeDir = findPackageDir('web-tree-sitter');
const grammarDir = path.join(findPackageDir('@vscode/tree-sitter-wasm'), 'wasm');

const inputs = [['runtime', path.join(runtimeDir, 'tree-sitter.wasm')]];
for (const [id, file] of Object.entries(GRAMMARS)) inputs.push([id, path.join(grammarDir, file)]);

const buffers = inputs.map(([id, file]) => {
  if (!existsSync(file)) throw new Error(`[gen-wasm-assets] missing ${file}`);
  return [id, readFileSync(file)];
});

const fingerprint = createHash('sha256');
for (const [id, buf] of buffers) fingerprint.update(id).update(buf);
const digest = fingerprint.digest('hex');

if (existsSync(outFile)) {
  const head = readFileSync(outFile, 'utf-8').slice(0, 400);
  if (head.includes(`inputs-sha256: ${digest}`)) {
    process.exit(0);
  }
}

const runtimeVersion = JSON.parse(readFileSync(path.join(runtimeDir, 'package.json'), 'utf-8')).version;
const grammarVersion = JSON.parse(
  readFileSync(path.join(path.dirname(grammarDir), 'package.json'), 'utf-8')
).version;

const lines = [
  '// AUTO-GENERATED by scripts/gen-wasm-assets.mjs — do not edit, do not commit.',
  `// inputs-sha256: ${digest}`,
  '/* eslint-disable */',
  `export const WASM_RUNTIME_VERSION = ${JSON.stringify(runtimeVersion)};`,
  `export const WASM_GRAMMARS_VERSION = ${JSON.stringify(grammarVersion)};`,
  '/** gzip + base64 of each WASM binary. */',
  'export const WASM_ASSETS: Record<string, string> = {',
];
let total = 0;
for (const [id, buf] of buffers) {
  const b64 = gzipSync(buf, { level: 9 }).toString('base64');
  total += b64.length;
  lines.push(`  ${JSON.stringify(id)}: ${JSON.stringify(b64)},`);
}
lines.push('};', '');

mkdirSync(path.dirname(outFile), { recursive: true });
writeFileSync(outFile, lines.join('\n'));
console.log(`[gen-wasm-assets] wrote ${path.relative(serverDir, outFile)} (${(total / 1024 / 1024).toFixed(2)} MB base64)`);
